def _compute_reservations_count(self):
    pms_reservation_obj = self.env["pms.reservation"]
    for record in self:
        record.reservations_count = pms_reservation_obj.search_count(
            [
                (
                    "partner_id",
                    "child_of",
                    record.id if isinstance(record.id, int) else False,
                )
            ]
        )
